INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_001', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_physics-and-measurement', 'exam_neet_physics_physics-and-measurement_units-and-measurements', 'Which of the following SI base units is used to measure luminous intensity?', 'single_choice', 'easy', 'The SI base unit of luminous intensity is the candela (cd). Mole measures amount of substance, kelvin measures temperature, and ampere measures electric current.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy001_a', 'q_auth_phy_001', 1, 'A', 'Candela', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy001_b', 'q_auth_phy_001', 2, 'B', 'Mole', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy001_c', 'q_auth_phy_001', 3, 'C', 'Kelvin', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy001_d', 'q_auth_phy_001', 4, 'D', 'Ampere', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_002', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_physics-and-measurement', 'exam_neet_physics_physics-and-measurement_units-and-measurements', 'The watt is the SI unit of power. Expressed purely in SI base units, 1 watt equals:', 'single_choice', 'medium', 'Power = energy/time, and 1 J = 1 N·m = 1 kg·m²·s⁻². Dividing by seconds gives 1 W = 1 kg·m²·s⁻³.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy002_a', 'q_auth_phy_002', 1, 'A', 'kg·m²·s⁻³', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy002_b', 'q_auth_phy_002', 2, 'B', 'kg·m·s⁻²', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy002_c', 'q_auth_phy_002', 3, 'C', 'kg·m²·s⁻²', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy002_d', 'q_auth_phy_002', 4, 'D', 'kg·m⁻¹·s⁻³', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_003', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_physics-and-measurement', 'exam_neet_physics_physics-and-measurement_dimensional-analysis', 'Which physical quantity has the same dimensional formula as impulse?', 'single_choice', 'easy', 'Impulse = force × time = (MLT⁻²)(T) = MLT⁻¹, which is exactly the dimensional formula of momentum — consistent with the impulse–momentum theorem.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy003_a', 'q_auth_phy_003', 1, 'A', 'Momentum', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy003_b', 'q_auth_phy_003', 2, 'B', 'Force', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy003_c', 'q_auth_phy_003', 3, 'C', 'Energy', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy003_d', 'q_auth_phy_003', 4, 'D', 'Power', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_004', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_physics-and-measurement', 'exam_neet_physics_physics-and-measurement_dimensional-analysis', 'For the viscous force F = η·A·(dv/dx) acting between fluid layers, the dimensional formula of the coefficient of viscosity η is:', 'single_choice', 'medium', 'Rearranging, η = F·x/(A·v). Substituting dimensions: (MLT⁻²·L)/(L²·LT⁻¹) = ML⁻¹T⁻¹, the standard dimension of viscosity (SI unit: pascal-second).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy004_a', 'q_auth_phy_004', 1, 'A', '[ML⁻¹T⁻¹]', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy004_b', 'q_auth_phy_004', 2, 'B', '[MLT⁻¹]', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy004_c', 'q_auth_phy_004', 3, 'C', '[ML⁻²T⁻¹]', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy004_d', 'q_auth_phy_004', 4, 'D', '[ML⁻¹T⁻²]', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_005', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinematics', 'exam_neet_physics_kinematics_motion-in-straight-line', 'A car covers the first half of the distance between two towns at 40 km/h and the second half at 60 km/h. Its average speed for the whole journey is:', 'single_choice', 'hard', 'For equal distances, average speed is the harmonic mean: 2v₁v₂/(v₁+v₂) = 2×40×60/100 = 48 km/h. The naive arithmetic mean (50 km/h) is incorrect because more time is spent at the slower speed.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy005_a', 'q_auth_phy_005', 1, 'A', '48 km/h', 1) ON CONFLICT (id) DO NOTHING;
