INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_006', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinematics', 'exam_neet_physics_kinematics_motion-in-straight-line', 'A cyclist rides along a straight road at a constant speed of 10 m/s. How far does she travel in 5 s?', 'single_choice', 'easy', 'For constant speed, distance = speed × time = 10 × 5 = 50 m.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
