INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_007', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinematics', 'exam_neet_physics_kinematics_uniformly-accelerated-motion', 'A body moving with uniform acceleration covers 40 m in the first 4 s and 80 m in the next 4 s. Its initial velocity and acceleration are:', 'single_choice', 'hard', 'First interval: s = 4u + 8a = 40 → u + 2a = 10. Total in 8 s: 8u + 32a = 120 → u + 4a = 15. Subtracting gives a = 2.5 m/s² and u = 5 m/s.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
