INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_008', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinematics', 'exam_neet_physics_kinematics_uniformly-accelerated-motion', 'A ball is thrown vertically upward with a speed of 20 m/s (g = 10 m/s²). The maximum height it reaches is:', 'single_choice', 'easy', 'At the highest point v = 0, so h = u²/(2g) = 20²/(2×10) = 400/20 = 20 m.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
