INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_009', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinematics', 'exam_neet_physics_kinematics_projectile-and-circular-motion', 'For a projectile launched from and landing on the same horizontal level, its velocity at the highest point of the trajectory is:', 'single_choice', 'easy', 'At the highest point the vertical component of velocity is momentarily zero, but the horizontal component (u cosθ) remains unchanged, so the velocity is entirely horizontal.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
