INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_010', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinematics', 'exam_neet_physics_kinematics_projectile-and-circular-motion', 'A projectile is launched at 45° to the horizontal with speed 20 m/s (g = 10 m/s²). Its time of flight is:', 'single_choice', 'medium', 'T = 2u·sinθ/g = 2×20×sin45°/10 = 4×(√2/2) = 2√2 ≈ 2.8 s.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
