INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_011', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinematics', 'exam_neet_physics_kinematics_projectile-and-circular-motion', 'A particle moves with a constant speed of 6 m/s in a circle of radius 2 m. The magnitude of its centripetal acceleration is:', 'single_choice', 'medium', 'Centripetal acceleration a = v²/r = 6²/2 = 36/2 = 18 m/s², directed toward the centre of the circle.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
