INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_012', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_laws-of-motion', 'exam_neet_physics_laws-of-motion_conservation-of-momentum', 'A 2 kg trolley moving at 3 m/s collides with and sticks to a stationary 1 kg trolley. Their common velocity immediately after the collision is:', 'single_choice', 'medium', 'Momentum is conserved in the absence of external forces: 2×3 = (2+1)v, so v = 6/3 = 2 m/s.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
