INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_013', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_laws-of-motion', 'exam_neet_physics_laws-of-motion_conservation-of-momentum', 'A rifle of mass 3 kg fires a bullet of mass 60 g and recoils at 1.5 m/s. The speed of the bullet as it leaves the rifle is:', 'single_choice', 'hard', 'By momentum conservation, 0.060 kg × v = 3 kg × 1.5 m/s = 4.5 kg·m/s, so v = 4.5/0.060 = 75 m/s. The bullet''s mass must be converted from grams to kilograms before dividing.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
