INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_014', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_laws-of-motion', 'exam_neet_physics_laws-of-motion_friction', 'The maximum value of static friction between two surfaces, reached just before sliding begins, is called:', 'single_choice', 'easy', 'Static friction adjusts up to a maximum called limiting friction; beyond this the surfaces begin to slide and kinetic friction takes over (usually slightly smaller).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
