INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_015', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_laws-of-motion', 'exam_neet_physics_laws-of-motion_friction', 'A 5 kg block on a horizontal floor (μk = 0.2) is pulled by a horizontal force of 20 N. Its acceleration is (g = 10 m/s²):', 'single_choice', 'hard', 'Normal reaction N = mg = 50 N, so kinetic friction f = μk·N = 0.2×50 = 10 N opposing the motion. Net force = 20 − 10 = 10 N, giving a = 10/5 = 2 m/s².', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
