INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_016', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_laws-of-motion', 'exam_neet_physics_laws-of-motion_circular-motion-dynamics', 'A car takes a flat (unbanked) circular turn of radius 50 m. If the coefficient of static friction is 0.4, the maximum speed at which it can take the turn without skidding is (g = 10 m/s²):', 'single_choice', 'medium', 'Friction provides the centripetal force: μmg ≥ mv²/r, so v_max = √(μgr) = √(0.4×10×50) = √200 = 10√2 ≈ 14.1 m/s.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy016_a', 'q_auth_phy_016', 1, 'A', '10√2 m/s ≈ 14.1 m/s', 1) ON CONFLICT (id) DO NOTHING;
