INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_017', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_laws-of-motion', 'exam_neet_physics_laws-of-motion_circular-motion-dynamics', 'A car moves at constant speed around a flat circular track. The net force on the car points:', 'single_choice', 'easy', 'Uniform circular motion requires a centripetal net force directed toward the centre of the circle; the speed stays constant because this force is perpendicular to the velocity.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
