INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_018', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_work-energy-and-power', 'exam_neet_physics_work-energy-and-power_work-energy-theorem', 'A 2 kg body is accelerated from 5 m/s to 10 m/s on a frictionless horizontal surface. The net work done on it is:', 'single_choice', 'medium', 'By the work–energy theorem, W_net = ΔKE = ½m(v² − u²) = ½×2×(100 − 25) = 75 J.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
