INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_019', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_work-energy-and-power', 'exam_neet_physics_work-energy-and-power_work-energy-theorem', 'The work done by the centripetal force on a particle completing one full circle in uniform circular motion is:', 'single_choice', 'easy', 'The centripetal force is always perpendicular to the instantaneous displacement, so W = F·s·cos90° = 0 at every point of the path.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
