INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy019_c', 'q_auth_phy_019', 3, 'C', 'Positive and constant', 0) ON CONFLICT (id) DO NOTHING;
