INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_020', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_work-energy-and-power', 'exam_neet_physics_work-energy-and-power_conservation-of-energy', 'A 1 kg ball dropped from a height of 5 m rebounds to a height of 2 m (g = 10 m/s²). The mechanical energy lost during the bounce is:', 'single_choice', 'medium', 'Initial PE = mgh₁ = 1×10×5 = 50 J; rebound PE = mgh₂ = 1×10×2 = 20 J. The difference, 30 J, is converted to heat, sound and deformation.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy020_a', 'q_auth_phy_020', 1, 'A', '30 J', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy020_b', 'q_auth_phy_020', 2, 'B', '20 J', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy020_c', 'q_auth_phy_020', 3, 'C', '50 J', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy020_d', 'q_auth_phy_020', 4, 'D', '10 J', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_021', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_work-energy-and-power', 'exam_neet_physics_work-energy-and-power_conservation-of-energy', 'A spring of stiffness k compressed by a distance x stores elastic energy ½kx². If the compression is doubled, the stored energy becomes:', 'single_choice', 'medium', 'E ∝ x². Doubling x gives E'' = ½k(2x)² = 4×(½kx²), i.e. four times the original energy.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy021_a', 'q_auth_phy_021', 1, 'A', 'Four times the original energy', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy021_b', 'q_auth_phy_021', 2, 'B', 'Twice the original energy', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy021_c', 'q_auth_phy_021', 3, 'C', 'Half the original energy', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy021_d', 'q_auth_phy_021', 4, 'D', 'Unchanged', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_022', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_work-energy-and-power', 'exam_neet_physics_work-energy-and-power_collisions', 'A ball moving at speed u undergoes a head-on elastic collision with an identical ball at rest on a frictionless surface. After the collision:', 'single_choice', 'medium', 'For equal masses in a 1-D elastic collision, the velocities are simply exchanged: the first ball comes to rest and the second moves off with speed u (both momentum and kinetic energy are conserved).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy022_a', 'q_auth_phy_022', 1, 'A', 'The first ball stops and the second moves off with speed u', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy022_b', 'q_auth_phy_022', 2, 'B', 'Both balls move together with speed u/2', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy022_c', 'q_auth_phy_022', 3, 'C', 'The first ball rebounds with speed u and the second stays at rest', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy022_d', 'q_auth_phy_022', 4, 'D', 'Both balls move forward, each with speed u/2', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_023', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_work-energy-and-power', 'exam_neet_physics_work-energy-and-power_collisions', 'A ball of mass m strikes a rigid wall at speed v and rebounds elastically along its original path at the same speed. The magnitude of the impulse imparted to the ball is:', 'single_choice', 'medium', 'Impulse = change in momentum = mv − (−mv) = 2mv, since the velocity reverses direction while keeping its magnitude.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
