INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy023_d', 'q_auth_phy_023', 4, 'D', 'mv/2', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_024', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_rotational-motion', 'exam_neet_physics_rotational-motion_torque-and-angular-momentum', 'A force of 10 N is applied at a point 2 m from a pivot, with the force making an angle of 30° with the position vector. The magnitude of the torque about the pivot is:', 'single_choice', 'medium', 'Torque τ = r·F·sinθ = 2×10×sin30° = 20×0.5 = 10 N·m. Only the component of force perpendicular to the position vector contributes.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
