INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_025', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_rotational-motion', 'exam_neet_physics_rotational-motion_moment-of-inertia', 'The moment of inertia of a uniform rod of mass M and length L about an axis through its centre and perpendicular to its length is:', 'single_choice', 'medium', 'For a uniform rod about its centre, I = ML²/12. About an axis through one end it is ML²/3, obtained from the parallel-axis theorem.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
