INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_026', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_gravitation', 'exam_neet_physics_gravitation_universal-law-of-gravitation', 'If the distance between two point masses is doubled, the gravitational force between them becomes:', 'single_choice', 'easy', 'F ∝ 1/r². Doubling r reduces the force by a factor of 2² = 4, so the new force is F/4.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
