INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_027', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_gravitation', 'exam_neet_physics_gravitation_universal-law-of-gravitation', 'The acceleration due to gravity at a height equal to the Earth''s radius R above the surface is (g = value at the surface):', 'single_choice', 'medium', 'g'' = g·R²/(R+h)². With h = R, g'' = g·R²/(2R)² = g/4.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
