INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy027_d', 'q_auth_phy_027', 4, 'D', 'g/16', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_028', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_gravitation', 'exam_neet_physics_gravitation_gravitational-potential-and-escape-velocity', 'The escape velocity from Earth''s surface is about 11.2 km/s. For a planet with twice Earth''s mass and the same radius, the escape velocity is:', 'single_choice', 'hard', 'v_e = √(2GM/R), so v_e ∝ √M for fixed R. Doubling M multiplies v_e by √2: 11.2×√2 ≈ 15.8 km/s.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy028_a', 'q_auth_phy_028', 1, 'A', '≈ 15.8 km/s', 1) ON CONFLICT (id) DO NOTHING;
