INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy028_c', 'q_auth_phy_028', 3, 'C', '≈ 11.2 km/s', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy028_d', 'q_auth_phy_028', 4, 'D', '≈ 7.9 km/s', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_029', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_gravitation', 'exam_neet_physics_gravitation_gravitational-potential-and-escape-velocity', 'A planet has the same average density as Earth but half Earth''s radius. The escape velocity from its surface is:', 'single_choice', 'hard', 'With M = (4/3)πR³ρ, v_e = R√(8πGρ/3), so for fixed density v_e ∝ R. Half the radius gives half Earth''s escape velocity: 11.2/2 = 5.6 km/s.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
