INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_030', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_thermodynamics', 'exam_neet_physics_thermodynamics_zeroth-and-first-law', 'The Zeroth Law of Thermodynamics, which deals with systems in thermal equilibrium, provides the basis for the concept of:', 'single_choice', 'easy', 'If two systems are each in thermal equilibrium with a third, they are in equilibrium with each other — this allows the definition of a common property called temperature.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
