INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_031', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_thermodynamics', 'exam_neet_physics_thermodynamics_zeroth-and-first-law', 'A gas absorbs 500 J of heat while doing 200 J of work on its surroundings. The change in its internal energy is:', 'single_choice', 'medium', 'First law: ΔU = Q − W (work done by the gas). ΔU = 500 − 200 = +300 J.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
