INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_032', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_thermodynamics', 'exam_neet_physics_thermodynamics_thermodynamic-processes', 'During the isothermal expansion of an ideal gas:', 'single_choice', 'medium', 'Isothermal means ΔT = 0, so for an ideal gas ΔU = 0. The first law then gives Q = W: all the heat absorbed is converted into work done by the gas.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
