INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_033', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_thermodynamics', 'exam_neet_physics_thermodynamics_second-law', 'A heat engine operates between a hot reservoir at 500 K and a cold reservoir at 300 K. Its maximum possible efficiency is:', 'single_choice', 'medium', 'For a Carnot engine, η = 1 − T_c/T_h = 1 − 300/500 = 0.40 = 40%. No engine between these reservoirs can do better.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
