INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_034', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinetic-theory-of-gases', 'exam_neet_physics_kinetic-theory-of-gases_equipartition-and-specific-heat', 'For a monatomic ideal gas, the ratio of specific heats γ = C_p/C_v equals:', 'single_choice', 'medium', 'A monatomic gas has 3 translational degrees of freedom: C_v = (3/2)R and C_p = (5/2)R, so γ = 5/3 ≈ 1.67.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
