INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_035', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_kinetic-theory-of-gases', 'exam_neet_physics_kinetic-theory-of-gases_equipartition-and-specific-heat', 'The total internal energy of one mole of a monatomic ideal gas at temperature T is:', 'single_choice', 'medium', 'Each of the 3 translational degrees of freedom carries (1/2)kT per molecule, giving U = (3/2)RT per mole by the law of equipartition.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
