INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy035_d', 'q_auth_phy_035', 4, 'D', 'RT', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_036', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_electrostatics', 'exam_neet_physics_electrostatics_coulombs-law-and-electric-field', 'Two point charges +q and +4q are fixed a distance d apart. The point on the line joining them where the net electric field is zero is located:', 'single_choice', 'hard', 'Setting kq/x² = k·4q/(d−x)² gives (d−x)² = 4x², so d − x = 2x and x = d/3. The null point lies d/3 from +q, closer to the smaller charge.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy036_a', 'q_auth_phy_036', 1, 'A', 'At a distance d/3 from the charge +q', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy036_b', 'q_auth_phy_036', 2, 'B', 'Exactly midway between the charges', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy036_c', 'q_auth_phy_036', 3, 'C', 'At a distance 2d/3 from the charge +q', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy036_d', 'q_auth_phy_036', 4, 'D', 'At a distance d/4 from the charge +q', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_037', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_electrostatics', 'exam_neet_physics_electrostatics_coulombs-law-and-electric-field', 'Two electric field lines can never cross each other because:', 'single_choice', 'easy', 'At any point the electric field has a single unique direction. If two lines crossed, there would be two directions for the field at the same point, which is impossible.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy037_a', 'q_auth_phy_037', 1, 'A', 'The field has a unique direction at every point', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy037_b', 'q_auth_phy_037', 2, 'B', 'Field lines always repel each other like charges', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy037_c', 'q_auth_phy_037', 3, 'C', 'The field strength would become infinite where they cross', 0) ON CONFLICT (id) DO NOTHING;
