INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_038', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_electrostatics', 'exam_neet_physics_electrostatics_electric-potential-and-dipole', 'The work done in moving a test charge between two points lying on the same equipotential surface is:', 'single_choice', 'easy', 'Work = q·ΔV. Since both points are at the same potential, ΔV = 0 and hence no net work is done (the path may still require force, but the net work is zero).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
