INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_039', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_electrostatics', 'exam_neet_physics_electrostatics_capacitance', 'A 2 μF and a 3 μF capacitor are connected in series. Their equivalent capacitance is:', 'single_choice', 'medium', 'For capacitors in series, 1/C = 1/C₁ + 1/C₂, so C = C₁C₂/(C₁+C₂) = 6/5 = 1.2 μF. Series capacitance is always smaller than either capacitor.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
