INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_040', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_electrostatics', 'exam_neet_physics_electrostatics_capacitance', 'A parallel-plate capacitor is charged and then disconnected from the battery. If the plate separation is then doubled, the energy stored in the capacitor:', 'single_choice', 'hard', 'With the battery disconnected, the charge Q is fixed. Doubling the separation halves C, and U = Q²/(2C) therefore doubles — the external work done pulling the plates apart is stored as extra field energy.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
