INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_041', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_current-electricity', 'exam_neet_physics_current-electricity_electric-current-and-ohms-law', 'A wire of resistance R is uniformly stretched to double its length, keeping its volume constant. Its new resistance is:', 'single_choice', 'hard', 'Volume constant means L doubles and the cross-sectional area halves. R'' = ρ(2L)/(A/2) = 4ρL/A = 4R.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
