INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_043', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_magnetic-effects-of-current', 'exam_neet_physics_magnetic-effects-of-current_biot-savart-and-amperes-law', 'The magnitude of the magnetic field at the centre of a circular loop of radius R carrying current I is:', 'single_choice', 'medium', 'By the Biot–Savart law, B = μ₀I/(2R) at the centre of a full circular loop — π times the field of a single straight wire at the same distance.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
