INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_045', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_magnetic-effects-of-current', 'exam_neet_physics_magnetic-effects-of-current_magnetic-forces-and-galvanometer', 'To convert a galvanometer into an ammeter that can measure larger currents, one connects:', 'single_choice', 'medium', 'A low-resistance shunt is connected in parallel with the galvanometer so that most of the current bypasses the sensitive coil while the instrument reads the total current. (A voltmeter, in contrast, uses a high resistance in series.)', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
