INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_048', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_optics', 'exam_neet_physics_optics_wave-optics-interference-diffraction', 'In a Young''s double-slit experiment, the entire apparatus is immersed in water (refractive index 4/3). The fringe width:', 'single_choice', 'hard', 'Fringe width β = λD/d. In water the wavelength shrinks to λ/n = 3λ/4, so β becomes 3/4 of its air value. (Slit separation d and screen distance D are unchanged.)', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
