INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy048_c', 'q_auth_phy_048', 3, 'C', 'Remains unchanged', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy048_d', 'q_auth_phy_048', 4, 'D', 'Doubles', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_049', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_dual-nature-of-matter-and-radiation', 'exam_neet_physics_dual-nature-of-matter-and-radiation_photoelectric-effect', 'In a photoelectric experiment using monochromatic light of fixed frequency above the threshold, the intensity of the light is increased. What happens?', 'single_choice', 'medium', 'Intensity determines the number of photons per second, so the photocurrent (number of emitted electrons) increases. Each photon still has the same energy hf, so the maximum kinetic energy of the electrons is unchanged.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy049_a', 'q_auth_phy_049', 1, 'A', 'The saturation current increases but the maximum kinetic energy of photoelectrons is unchanged', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy049_b', 'q_auth_phy_049', 2, 'B', 'Both the saturation current and the maximum kinetic energy increase', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy049_c', 'q_auth_phy_049', 3, 'C', 'Only the maximum kinetic energy increases', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy049_d', 'q_auth_phy_049', 4, 'D', 'Neither the current nor the kinetic energy changes', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_phy_050', 'exam_neet', 'exam_neet_physics', 'exam_neet_physics_atoms-and-nuclei', 'exam_neet_physics_atoms-and-nuclei_nuclear-structure-and-reactions', 'The enormous energy released in nuclear fission is fundamentally due to:', 'single_choice', 'easy', 'The total mass of the fission products is slightly less than the mass of the original nucleus. This mass defect Δm is converted to energy according to Einstein''s relation E = Δmc².', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_phy050_a', 'q_auth_phy_050', 1, 'A', 'Conversion of the mass defect into energy (E = Δmc²)', 1) ON CONFLICT (id) DO NOTHING;
