INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_003', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_basic-concepts-of-chemistry', 'exam_neet_chemistry_basic-concepts-of-chemistry_matter-and-mole-concept', 'The mass of 0.25 mol of calcium carbonate, CaCO₃ (Ca = 40, C = 12, O = 16), is:', 'single_choice', 'medium', 'Molar mass of CaCO₃ = 40 + 12 + (3×16) = 100 g/mol. Mass = 0.25 × 100 = 25 g.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
