INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_004', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_basic-concepts-of-chemistry', 'exam_neet_chemistry_basic-concepts-of-chemistry_stoichiometry-and-concentration', '4 g of NaOH (molar mass 40 g/mol) is dissolved in water to make 500 mL of solution. The molarity of the solution is:', 'single_choice', 'medium', 'Moles of NaOH = 4/40 = 0.1 mol. Volume = 0.5 L. Molarity = 0.1/0.5 = 0.2 M.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
