INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_005', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_basic-concepts-of-chemistry', 'exam_neet_chemistry_basic-concepts-of-chemistry_stoichiometry-and-concentration', 'For the reaction 2H₂(g) + O₂(g) → 2H₂O(g), 4 mol of H₂ is mixed with 3 mol of O₂. Which statement is correct?', 'single_choice', 'hard', 'The stoichiometric ratio is H₂ : O₂ = 2 : 1. Four moles of H₂ require only 2 mol of O₂, so H₂ is the limiting reagent. Product formed = moles of H₂ (1:1 with H₂O) = 4 mol H₂O, leaving 1 mol O₂ unreacted.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm005_a', 'q_auth_chm_005', 1, 'A', 'H₂ is the limiting reagent and 4 mol of H₂O are formed', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm005_b', 'q_auth_chm_005', 2, 'B', 'O₂ is the limiting reagent and 6 mol of H₂O are formed', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm005_c', 'q_auth_chm_005', 3, 'C', 'H₂ is the limiting reagent and 2 mol of H₂O are formed', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm005_d', 'q_auth_chm_005', 4, 'D', 'O₂ is the limiting reagent and 3 mol of H₂O are formed', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_006', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_atomic-structure', 'exam_neet_chemistry_atomic-structure_bohr-model-and-quantum-mechanics', 'In the Bohr model of the hydrogen atom, the energy of an electron in a stationary state depends on:', 'single_choice', 'easy', 'For hydrogen, E_n = −13.6/n² eV, so the energy depends only on the principal quantum number n. (l and m do not appear in the Bohr picture.)', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
