INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_013', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-bonding', 'exam_neet_chemistry_chemical-bonding_ionic-and-covalent-bonding', 'Which of the following species contains a coordinate (dative) covalent bond in which both electrons of the shared pair come from the same atom?', 'single_choice', 'medium', 'In NH₄⁺, the nitrogen of NH₃ donates its lone pair to a proton (H⁺), forming a coordinate N→H bond in addition to the three normal N–H bonds.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
