INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_014', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-bonding', 'exam_neet_chemistry_chemical-bonding_ionic-and-covalent-bonding', 'The lattice enthalpy of an ionic compound is largest when the constituent ions are:', 'single_choice', 'medium', 'Lattice enthalpy ∝ (q₁·q₂)/r. Small, highly charged ions pack close together and attract strongly, so small radii and high charges maximize lattice enthalpy (e.g. MgO vs NaCl).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
