INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_015', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-bonding', 'exam_neet_chemistry_chemical-bonding_molecular-orbital-theory', 'According to molecular orbital theory, the bond order of the O₂ molecule is:', 'single_choice', 'easy', 'O₂ has 10 electrons in bonding MOs and 6 in antibonding MOs. Bond order = (10 − 6)/2 = 2, consistent with the O=O double bond picture.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
