INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_016', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-bonding', 'exam_neet_chemistry_chemical-bonding_molecular-orbital-theory', 'Which of the following species is paramagnetic (contains unpaired electrons)?', 'single_choice', 'hard', 'O₂⁻ (superoxide) has one unpaired antibonding electron, so it is paramagnetic. O₂²⁻ (peroxide), NO⁺ and CN⁻ all have closed-shell configurations and are diamagnetic.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
