INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_017', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-thermodynamics', 'exam_neet_chemistry_chemical-thermodynamics_thermochemistry-hess-law', 'Hess''s law of constant heat summation states that the total enthalpy change of a reaction depends on:', 'single_choice', 'easy', 'Enthalpy is a state function, so the overall ΔH depends only on the initial and final states of the system, not on the particular steps or path taken.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
