INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_018', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-thermodynamics', 'exam_neet_chemistry_chemical-thermodynamics_thermochemistry-hess-law', 'Given: (i) C(s) + O₂(g) → CO₂(g), ΔH = −393.5 kJ/mol and (ii) CO(g) + ½O₂(g) → CO₂(g), ΔH = −283.0 kJ/mol. The enthalpy of formation of CO(g) from C(s) and ½O₂(g) is:', 'single_choice', 'hard', 'By Hess''s law, reaction (i) = desired reaction + (ii). ΔH(desired) = ΔH(i) − ΔH(ii) = −393.5 − (−283.0) = −110.5 kJ/mol.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm018_a', 'q_auth_chm_018', 1, 'A', '−110.5 kJ/mol', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm018_b', 'q_auth_chm_018', 2, 'B', '−676.5 kJ/mol', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm018_c', 'q_auth_chm_018', 3, 'C', '+110.5 kJ/mol', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm018_d', 'q_auth_chm_018', 4, 'D', '−393.5 kJ/mol', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_019', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-thermodynamics', 'exam_neet_chemistry_chemical-thermodynamics_spontaneity-entropy-gibbs-energy', 'A process is spontaneous at ALL temperatures when:', 'single_choice', 'medium', 'ΔG = ΔH − TΔS. If ΔH < 0 and ΔS > 0, then ΔG is negative at every temperature, so the process is spontaneous at all temperatures.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm019_a', 'q_auth_chm_019', 1, 'A', 'ΔH < 0 and ΔS > 0', 1) ON CONFLICT (id) DO NOTHING;
