INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm019_c', 'q_auth_chm_019', 3, 'C', 'ΔH < 0 and ΔS < 0', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm019_d', 'q_auth_chm_019', 4, 'D', 'ΔH > 0 and ΔS < 0', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_020', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-thermodynamics', 'exam_neet_chemistry_chemical-thermodynamics_spontaneity-entropy-gibbs-energy', 'At constant temperature and pressure, a process is spontaneous when the change in Gibbs energy (ΔG) is:', 'single_choice', 'easy', 'The criterion for spontaneity at constant T and P is ΔG < 0. ΔG = 0 means equilibrium, and ΔG > 0 means the process is non-spontaneous in the forward direction.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm020_a', 'q_auth_chm_020', 1, 'A', 'Negative (ΔG < 0)', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm020_b', 'q_auth_chm_020', 2, 'B', 'Positive (ΔG > 0)', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm020_c', 'q_auth_chm_020', 3, 'C', 'Exactly zero', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm020_d', 'q_auth_chm_020', 4, 'D', 'Positive or zero', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_021', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_solutions', 'exam_neet_chemistry_solutions_types-of-solutions-and-raoults-law', 'For a binary solution to be truly ideal, it must obey Raoult''s law over the entire concentration range and have:', 'single_choice', 'medium', 'Ideal solutions form when unlike interactions match like interactions exactly: ΔH_mix = 0 and ΔV_mix = 0 (e.g. benzene + toluene, approximately).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm021_a', 'q_auth_chm_021', 1, 'A', 'ΔH_mix = 0 and ΔV_mix = 0', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm021_b', 'q_auth_chm_021', 2, 'B', 'ΔH_mix > 0 and ΔV_mix > 0', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm021_c', 'q_auth_chm_021', 3, 'C', 'ΔH_mix < 0 and ΔV_mix < 0', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm021_d', 'q_auth_chm_021', 4, 'D', 'ΔH_mix = 0 but ΔV_mix ≠ 0', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_022', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_solutions', 'exam_neet_chemistry_solutions_types-of-solutions-and-raoults-law', 'A liquid pair shows positive deviation from Raoult''s law when:', 'single_choice', 'medium', 'Positive deviation occurs when A–B interactions are weaker than A–A and B–B interactions, so molecules escape more easily and the vapour pressure exceeds the Raoult''s-law prediction (e.g. ethanol + acetone).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm022_a', 'q_auth_chm_022', 1, 'A', 'A–B interactions are weaker than A–A and B–B interactions, raising the vapour pressure above the predicted value', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm022_b', 'q_auth_chm_022', 2, 'B', 'A–B interactions are stronger than A–A and B–B interactions, lowering the vapour pressure below the predicted value', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm022_c', 'q_auth_chm_022', 3, 'C', 'The solution obeys Raoult''s law at all concentrations', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm022_d', 'q_auth_chm_022', 4, 'D', 'The vapour pressure is exactly equal to the pure-component vapour pressures', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_023', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_solutions', 'exam_neet_chemistry_solutions_colligative-properties-and-van-t-hoff', 'Which of the following is a colligative property?', 'single_choice', 'easy', 'Colligative properties depend only on the number of solute particles, not their identity. Osmotic pressure, boiling-point elevation, freezing-point depression and vapour-pressure lowering are the four colligative properties; viscosity and surface tension are not.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm023_a', 'q_auth_chm_023', 1, 'A', 'Osmotic pressure', 1) ON CONFLICT (id) DO NOTHING;
