INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm023_c', 'q_auth_chm_023', 3, 'C', 'Surface tension', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm023_d', 'q_auth_chm_023', 4, 'D', 'Refractive index', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_024', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_solutions', 'exam_neet_chemistry_solutions_colligative-properties-and-van-t-hoff', 'Assuming complete dissociation and ideal behaviour, which 0.1 M aqueous solution has the HIGHEST boiling point?', 'single_choice', 'hard', 'Boiling-point elevation ∝ i·m, where i is the number of ions per formula unit: glucose i = 1, NaCl i = 2, CaCl₂ i = 3, K₃PO₄ i = 4. K₃PO₄ releases the most particles and hence shows the largest elevation.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm024_a', 'q_auth_chm_024', 1, 'A', '0.1 M K₃PO₄', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm024_b', 'q_auth_chm_024', 2, 'B', '0.1 M CaCl₂', 0) ON CONFLICT (id) DO NOTHING;
