INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm024_d', 'q_auth_chm_024', 4, 'D', '0.1 M glucose', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_025', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_solutions', 'exam_neet_chemistry_solutions_colligative-properties-and-van-t-hoff', 'Assuming complete dissociation, the van ''t Hoff factor (i) for potassium sulphate, K₂SO₄, in water is:', 'single_choice', 'medium', 'K₂SO₄ dissociates into 2K⁺ + SO₄²⁻, giving 3 particles per formula unit, so i = 3.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm025_a', 'q_auth_chm_025', 1, 'A', '3', 1) ON CONFLICT (id) DO NOTHING;
