INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_026', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_equilibrium', 'exam_neet_chemistry_equilibrium_chemical-equilibrium-le-chatelier', 'For the exothermic industrial synthesis N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the yield of ammonia is increased by:', 'single_choice', 'medium', 'The forward reaction reduces the number of gas moles (4 → 2) and releases heat. By Le Chatelier''s principle, high pressure favours the forward reaction, and lower temperature favours the exothermic direction.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm026_a', 'q_auth_chm_026', 1, 'A', 'Increasing pressure and lowering the temperature', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm026_b', 'q_auth_chm_026', 2, 'B', 'Increasing temperature and decreasing pressure', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm026_c', 'q_auth_chm_026', 3, 'C', 'Decreasing the pressure over the mixture', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm026_d', 'q_auth_chm_026', 4, 'D', 'Continuously removing N₂ from the vessel', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_027', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_equilibrium', 'exam_neet_chemistry_equilibrium_chemical-equilibrium-le-chatelier', 'When a catalyst is added to a system already at equilibrium:', 'single_choice', 'medium', 'A catalyst lowers the activation energy of the forward and reverse reactions equally, so equilibrium is reached faster but its position (and K) is unchanged.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm027_a', 'q_auth_chm_027', 1, 'A', 'Equilibrium is reached faster, but the composition at equilibrium is unchanged', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm027_b', 'q_auth_chm_027', 2, 'B', 'The forward reaction is favoured and the yield increases', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm027_c', 'q_auth_chm_027', 3, 'C', 'The reverse reaction is favoured and the yield decreases', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm027_d', 'q_auth_chm_027', 4, 'D', 'The equilibrium constant increases', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_028', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_equilibrium', 'exam_neet_chemistry_equilibrium_chemical-equilibrium-le-chatelier', 'For the equilibrium PCl₅(g) ⇌ PCl₃(g) + Cl₂(g), the volume of the vessel is suddenly decreased at constant temperature. What happens?', 'single_choice', 'hard', 'Compressing the mixture raises the pressure, so the equilibrium shifts toward the side with fewer gas moles (PCl₅, backward). However, Kc depends only on temperature, so its value is unchanged.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm028_a', 'q_auth_chm_028', 1, 'A', 'The equilibrium shifts backward (more PCl₅) but Kc remains unchanged', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm028_b', 'q_auth_chm_028', 2, 'B', 'The equilibrium shifts forward (more PCl₃ and Cl₂) but Kc remains unchanged', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm028_c', 'q_auth_chm_028', 3, 'C', 'The equilibrium shifts backward and Kc decreases', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm028_d', 'q_auth_chm_028', 4, 'D', 'There is no shift and Kc increases', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_029', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_equilibrium', 'exam_neet_chemistry_equilibrium_ionic-equilibrium-and-ph', 'The pH of a neutral aqueous solution at 25°C is:', 'single_choice', 'easy', 'At 25°C, [H⁺] = [OH⁻] = 10⁻⁷ M in pure water, so pH = −log(10⁻⁷) = 7.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm029_a', 'q_auth_chm_029', 1, 'A', '7', 1) ON CONFLICT (id) DO NOTHING;
