INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm029_c', 'q_auth_chm_029', 3, 'C', '14', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm029_d', 'q_auth_chm_029', 4, 'D', '1', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_030', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_equilibrium', 'exam_neet_chemistry_equilibrium_ionic-equilibrium-and-ph', 'The pH of a 0.001 M solution of HCl, a strong acid that ionizes completely, is:', 'single_choice', 'medium', 'Complete ionization gives [H⁺] = 10⁻³ M, so pH = −log(10⁻³) = 3.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm030_a', 'q_auth_chm_030', 1, 'A', '3', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm030_b', 'q_auth_chm_030', 2, 'B', '11', 0) ON CONFLICT (id) DO NOTHING;
