INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm030_d', 'q_auth_chm_030', 4, 'D', '1', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_031', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_equilibrium', 'exam_neet_chemistry_equilibrium_solubility-product', 'The solubility product of AgCl at 25°C is 1.8×10⁻¹⁰. Its molar solubility in pure water is:', 'single_choice', 'hard', 'For AgCl ⇌ Ag⁺ + Cl⁻, Ksp = s². So s = √(1.8×10⁻¹⁰) = √1.8 × 10⁻⁵ ≈ 1.34×10⁻⁵ M.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm031_a', 'q_auth_chm_031', 1, 'A', '≈ 1.34×10⁻⁵ M', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm031_b', 'q_auth_chm_031', 2, 'B', '1.8×10⁻¹⁰ M', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm031_c', 'q_auth_chm_031', 3, 'C', '≈ 1.34×10⁻¹⁰ M', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm031_d', 'q_auth_chm_031', 4, 'D', '≈ 3.6×10⁻⁵ M', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_032', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_equilibrium', 'exam_neet_chemistry_equilibrium_solubility-product', 'When AgCl (Ksp = 1.8×10⁻¹⁰) is placed in 0.1 M NaCl solution instead of pure water, its molar solubility:', 'single_choice', 'hard', 'The common ion Cl⁻ suppresses dissolution: s = Ksp/[Cl⁻] = 1.8×10⁻¹⁰/0.1 = 1.8×10⁻⁹ M — far below the pure-water value of ≈1.34×10⁻⁵ M (the common-ion effect).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm032_a', 'q_auth_chm_032', 1, 'A', 'Drops to about 1.8×10⁻⁹ M because of the common-ion effect', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm032_b', 'q_auth_chm_032', 2, 'B', 'Increases because Na⁺ helps dissolve AgCl', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm032_c', 'q_auth_chm_032', 3, 'C', 'Stays the same as in pure water', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm032_d', 'q_auth_chm_032', 4, 'D', 'Becomes exactly zero because AgCl is insoluble', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_033', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry_redox-reactions-and-oxidation-number', 'The oxidation state of manganese in KMnO₄ is:', 'single_choice', 'easy', 'K is +1 and each O is −2: (+1) + x + 4(−2) = 0, giving x = +7.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm033_a', 'q_auth_chm_033', 1, 'A', '+7', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm033_b', 'q_auth_chm_033', 2, 'B', '+6', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm033_c', 'q_auth_chm_033', 3, 'C', '+4', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm033_d', 'q_auth_chm_033', 4, 'D', '+2', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_034', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry_redox-reactions-and-oxidation-number', 'In the spontaneous reaction Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s):', 'single_choice', 'easy', 'Zn loses electrons (oxidation number 0 → +2), so Zn is oxidised and acts as the reducing agent. Cu²⁺ gains electrons (+2 → 0), so it is reduced and acts as the oxidising agent.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm034_a', 'q_auth_chm_034', 1, 'A', 'Zn is oxidised and Cu²⁺ is reduced', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm034_b', 'q_auth_chm_034', 2, 'B', 'Zn is reduced and Cu²⁺ is oxidised', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm034_c', 'q_auth_chm_034', 3, 'C', 'Both Zn and Cu²⁺ are oxidised', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm034_d', 'q_auth_chm_034', 4, 'D', 'Neither species changes its oxidation state', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_035', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry_galvanic-cells-and-nernst-equation', 'In a galvanic (voltaic) cell, oxidation takes place at the:', 'single_choice', 'easy', 'Oxidation (loss of electrons) always occurs at the anode, reduction at the cathode; in a galvanic cell the anode is the negative terminal.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm035_a', 'q_auth_chm_035', 1, 'A', 'Anode', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm035_b', 'q_auth_chm_035', 2, 'B', 'Cathode', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm035_c', 'q_auth_chm_035', 3, 'C', 'Salt bridge', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm035_d', 'q_auth_chm_035', 4, 'D', 'Voltmeter', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_036', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry', 'exam_neet_chemistry_redox-reactions-and-electrochemistry_galvanic-cells-and-nernst-equation', 'For the cell Zn(s) | Zn²⁺(aq) || Cu²⁺(aq) | Cu(s) with E°cell = 1.10 V, increasing the concentration of Cu²⁺ (while [Zn²⁺] is held constant) will:', 'single_choice', 'hard', 'E = E° − (0.059/2)·log([Zn²⁺]/[Cu²⁺]). Raising [Cu²⁺] decreases the reaction quotient Q, so the logarithmic term shrinks and the cell EMF rises above its standard value.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm036_a', 'q_auth_chm_036', 1, 'A', 'Increase the cell EMF above 1.10 V', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm036_b', 'q_auth_chm_036', 2, 'B', 'Decrease the cell EMF below 1.10 V', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm036_c', 'q_auth_chm_036', 3, 'C', 'Leave the EMF unchanged at 1.10 V', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm036_d', 'q_auth_chm_036', 4, 'D', 'Reverse the direction of the cell reaction', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_037', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-kinetics', 'exam_neet_chemistry_chemical-kinetics_rate-of-reaction-and-order', 'For a zero-order reaction, the rate of the reaction:', 'single_choice', 'easy', 'By definition, a zero-order rate is independent of reactant concentration: rate = k[A]⁰ = k, constant until the reactant is exhausted.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm037_a', 'q_auth_chm_037', 1, 'A', 'Is independent of the concentration of the reactant', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm037_b', 'q_auth_chm_037', 2, 'B', 'Doubles when the reactant concentration doubles', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm037_c', 'q_auth_chm_037', 3, 'C', 'Is proportional to the square of the reactant concentration', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm037_d', 'q_auth_chm_037', 4, 'D', 'Increases exponentially with time', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_038', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-kinetics', 'exam_neet_chemistry_chemical-kinetics_rate-of-reaction-and-order', 'A reaction follows the rate law rate = k[A][B]². If [A] is doubled and [B] is also doubled, the rate increases by a factor of:', 'single_choice', 'medium', 'Rate ∝ [A]¹[B]². Doubling [A] contributes a factor of 2, doubling [B] contributes 2² = 4, so the total factor is 2 × 4 = 8.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm038_a', 'q_auth_chm_038', 1, 'A', '8', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm038_b', 'q_auth_chm_038', 2, 'B', '4', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm038_c', 'q_auth_chm_038', 3, 'C', '6', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm038_d', 'q_auth_chm_038', 4, 'D', '2', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_039', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_chemical-kinetics', 'exam_neet_chemistry_chemical-kinetics_integrated-rate-equations', 'For a first-order reaction with rate constant k = 0.693 min⁻¹, the half-life of the reaction is:', 'single_choice', 'medium', 'For a first-order reaction, t½ = 0.693/k = 0.693/0.693 = 1 min. The half-life is independent of the initial concentration.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
