INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_041', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_classification-of-elements', 'exam_neet_chemistry_classification-of-elements_periodic-table-and-trends', 'Which of the following correctly represents the decrease in atomic radius across Period 3?', 'single_choice', 'easy', 'Across a period, nuclear charge increases while electrons enter the same shell, pulling them closer. Atomic radius therefore decreases from Na to Mg to Al.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
