INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_chm_042', 'exam_neet', 'exam_neet_chemistry', 'exam_neet_chemistry_classification-of-elements', 'exam_neet_chemistry_classification-of-elements_periodic-table-and-trends', 'Boron has a lower first ionization enthalpy than beryllium, although its nuclear charge is higher, because:', 'single_choice', 'hard', 'Be loses a 2s electron, while B loses a 2p electron. The 2p electron is higher in energy and more shielded than the penetrating 2s electron, so it is easier to remove — an exception to the general period trend.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_chm042_a', 'q_auth_chm_042', 1, 'A', 'Boron''s outermost electron is a 2p electron, which is higher in energy and more shielded than beryllium''s 2s electron', 1) ON CONFLICT (id) DO NOTHING;
