INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_bio_033', 'exam_neet', 'exam_neet_biology', 'exam_neet_biology_genetics-and-evolution', 'exam_neet_biology_genetics-and-evolution_principles-of-inheritance', 'Mendel''s law of segregation states that during gamete formation:', 'single_choice', 'easy', 'The two alleles of a gene pair segregate (separate) from each other so that each gamete carries only one allele; this is the basis of the 3:1 monohybrid F₂ ratio.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
