INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_bio_034', 'exam_neet', 'exam_neet_biology', 'exam_neet_biology_genetics-and-evolution', 'exam_neet_biology_genetics-and-evolution_principles-of-inheritance', 'A heterozygous tall pea plant (Tt) is crossed with a homozygous dwarf plant (tt). The expected ratio of tall to dwarf offspring is:', 'single_choice', 'medium', 'The Tt parent produces T and t gametes equally; the tt parent produces only t. Offspring are ½ Tt (tall) and ½ tt (dwarf) — a 1:1 ratio, the classic test-cross result.', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
