INSERT INTO questions (id, exam_id, subject_id, chapter_id, topic_id, text, type, difficulty, explanation, source, source_url, attribution, license, external_id, year, provenance, status, created_at, updated_at) VALUES ('q_auth_bio_035', 'exam_neet', 'exam_neet_biology', 'exam_neet_biology_genetics-and-evolution', 'exam_neet_biology_genetics-and-evolution_principles-of-inheritance', 'Colour blindness is an X-linked recessive trait. A carrier mother (X^C X^c) and a normal father (X^C Y) have children. What fraction of their SONS is expected to be colour-blind?', 'single_choice', 'hard', 'Sons receive their single X chromosome from the mother: half get X^C (normal vision) and half get X^c (colour-blind). So 50% of sons are affected, while no daughters are (they all receive the father''s normal X^C).', 'ParikshaVerse Authored Bank', NULL, 'Original practice content', NULL, NULL, NULL, 'authored', 'active', 1790380800000, 1790380800000) ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (id, question_id, display_order, option_key, text, is_correct) VALUES ('opt_auth_bio035_a', 'q_auth_bio_035', 1, 'A', '50% of the sons', 1) ON CONFLICT (id) DO NOTHING;
